import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Optimized CUDA kernel with larger tile size, register blocking, and vectorization
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define BLOCK_ROWS 8

__global__ void matmul_kernel(const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C, int N) {
    // Shared memory for tiles with padding to avoid bank conflicts
    __shared__ float As[TILE_SIZE][TILE_SIZE+1];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE+1];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    // Each thread computes 4 elements of C
    int row = by * TILE_SIZE + ty * 4;
    int col = bx * TILE_SIZE + tx;

    // Register accumulation
    float c[4] = {0.0f};

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile from A (coalesced access)
        int a_col = t * TILE_SIZE + tx;
        if (row < N && a_col < N) {
            As[ty * 4][tx] = A[row * N + a_col];
            As[ty * 4 + 1][tx] = A[(row + 1) * N + a_col];
            As[ty * 4 + 2][tx] = A[(row + 2) * N + a_col];
            As[ty * 4 + 3][tx] = A[(row + 3) * N + a_col];
        } else {
            As[ty * 4][tx] = 0.0f;
            As[ty * 4 + 1][tx] = 0.0f;
            As[ty * 4 + 2][tx] = 0.0f;
            As[ty * 4 + 3][tx] = 0.0f;
        }

        // Load tile from B (coalesced access)
        int b_row = t * TILE_SIZE + ty * 4;
        if (b_row < N && col < N) {
            Bs[ty * 4][tx] = B[b_row * N + col];
            Bs[ty * 4 + 1][tx] = B[(b_row + 1) * N + col];
            Bs[ty * 4 + 2][tx] = B[(b_row + 2) * N + col];
            Bs[ty * 4 + 3][tx] = B[(b_row + 3) * N + col];
        } else {
            Bs[ty * 4][tx] = 0.0f;
            Bs[ty * 4 + 1][tx] = 0.0f;
            Bs[ty * 4 + 2][tx] = 0.0f;
            Bs[ty * 4 + 3][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum with loop unrolling
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; k++) {
            float a_val0 = As[ty * 4][k];
            float a_val1 = As[ty * 4 + 1][k];
            float a_val2 = As[ty * 4 + 2][k];
            float a_val3 = As[ty * 4 + 3][k];

            float b_val = Bs[k][tx];

            c[0] += a_val0 * b_val;
            c[1] += a_val1 * b_val;
            c[2] += a_val2 * b_val;
            c[3] += a_val3 * b_val;
        }

        __syncthreads();
    }

    // Write results with coalesced access
    if (row < N && col < N) {
        C[row * N + col] = c[0];
        if (row + 1 < N) C[(row + 1) * N + col] = c[1];
        if (row + 2 < N) C[(row + 2) * N + col] = c[2];
        if (row + 3 < N) C[(row + 3) * N + col] = c[3];
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, torch::device(torch::kCUDA).dtype(torch::kFloat));

    // Set block and grid dimensions
    dim3 threadsPerBlock(TILE_SIZE, BLOCK_ROWS);  // 32x8 threads
    dim3 numBlocks((N + TILE_SIZE - 1) / TILE_SIZE, 
                   (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<numBlocks, threadsPerBlock>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

cpp_source = """
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

# Compile the CUDA kernel
matmul_module = load_inline(
    name="matmul_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--use_fast_math", "-Xptxas=-v"]
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return matmul_module.matmul_cuda(A, B)"}

